  int add(int a, int b) { return a + b; }

  NB_MODULE(my_ext, m) {
      m.def("add", &add, "a"_a, "b"_a = 1,
            "This function adds two numbers and increments if only one is provided.");
      m.def("sum_1d_array", [](const nb::ndarray<const double, nb::ndim<1>>& a) {
          if (a.Order == 'C') {
              // Fast track
              auto v = a.view<const double, nb::ndim<1>, nb::c_contig>();
              double result = 0;
              for (size_t i = 0; i < v.shape(0); ++i) {
                  result += v(i);
              }
              return result;
          } else {
              double result = 0;
              for (size_t i = 0; i < a.shape(0); ++i) {
                  result += a(i);
              }
              return result;
          }
      });
  }
